'use client'

import * as React from 'react'

import './compare-slider.css'

export type CompareSliderProps = {
    before: React.ReactNode
    after: React.ReactNode
    /** Accessible name for the slider, e.g. "Before and after comparison". */
    label?: string
    /** Starting position, 0–100. */
    defaultValue?: number
    className?: string
}

// Before/after comparison driven by a real <input type="range">: arrow keys, Home/End,
// screen-reader value announcements and touch all come from the browser.
const CompareSlider = ({ before, after, label = 'Comparison position', defaultValue = 50, className }: CompareSliderProps) => {
    const [value, setValue] = React.useState(defaultValue)

    return <div className={['rad-fx-compare', className].filter(Boolean).join(' ')} style={{ '--rad-fx-compare': `${value}%` } as React.CSSProperties}>
        <div className="rad-fx-compare-layer">{after}</div>
        <div className="rad-fx-compare-layer rad-fx-compare-before">{before}</div>
        <div className="rad-fx-compare-handle" aria-hidden="true"><span /></div>
        <input
            type="range"
            min={0}
            max={100}
            value={value}
            aria-label={label}
            aria-valuetext={`${value}% before`}
            className="rad-fx-compare-input"
            onChange={(event) => setValue(Number(event.target.value))}
        />
    </div>
}

export default CompareSlider

.rad-fx-compare {
    position: relative;
    display: grid;
    overflow: hidden;
    border-radius: 16px;
    user-select: none;
}

.rad-fx-compare-layer { grid-area: 1 / 1; }

.rad-fx-compare-before { clip-path: inset(0 calc(100% - var(--rad-fx-compare, 50%)) 0 0); }

.rad-fx-compare-handle {
    position: absolute;
    top: 0;
    bottom: 0;
    left: var(--rad-fx-compare, 50%);
    width: 2px;
    margin-left: -1px;
    background: #fff;
    box-shadow: 0 0 12px rgb(0, 0, 0, 0.4);
    pointer-events: none;
}

.rad-fx-compare-handle span {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 2px 10px rgb(0, 0, 0, 0.35);
    transform: translate(-50%, -50%);
}

/* The real slider sits on top, invisible but focusable and draggable. */
.rad-fx-compare-input {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    opacity: 0;
    cursor: ew-resize;
}

.rad-fx-compare:has(.rad-fx-compare-input:focus-visible) .rad-fx-compare-handle span {
    outline: 3px solid #fff;
    outline-offset: 3px;
}
